{"command":"cat << 'EOF' > yaml_test.go
package main

import (
	"fmt"
	"strings"
)

func parseYAMLLines(lines []string, indent int, lineIdx int) (interface{}, int) {
	m := make(map[string]interface{})
	i := lineIdx
	for i < len(lines) {
		line := lines[i]
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			i++
			continue
		}
		curIndent := len(line) - len(strings.TrimLeft(line, " "))
		if curIndent < indent {
			break
		}

		colonIdx := strings.Index(line, ":")
		if colonIdx == -1 {
			i++
			continue
		}
		key := strings.TrimSpace(line[:colonIdx])
		valStr := strings.TrimSpace(line[colonIdx+1:])

		if valStr == "" {
			var child interface{}
			child, i = parseYAMLLines(lines, curIndent+1, i+1)
			m[key] = child
		} else {
			if strings.HasPrefix(valStr, "\"") && strings.HasSuffix(valStr, "\"") {
				m[key] = valStr[1 : len(valStr)-1]
			} else {
				m[key] = valStr
			}
			i++
		}
	}
	return m, i
}

func main() {
	yaml := `
foo:
  bar:
    baz: "hello"
  qux: world
`
	m, _ := parseYAMLLines(strings.Split(yaml, "\n"), 0, 0)
	fmt.Printf("%#v\n", m)
}
EOF
go run yaml_test.go"}

