func parseAliasURL(arg string) (string, string) {
	parts := strings.SplitN(arg, "=", 2)
	if len(parts) == 2 {
		return parts[0], parts[1]
	}
	base := filepath.Base(arg)
	ext := filepath.Ext(base)
	return strings.TrimSuffix(base, ext), arg
}

func parseYAMLLines(lines []string, indent int, lineIdx int) (interface{}, int) {
	m := make(map[string]interface{})
	i := lineIdx
	for i < len(lines) {
		line := lines[i]
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			i++
			continue
		}
		curIndent := len(line) - len(strings.TrimLeft(line, " "))
		if curIndent < indent {
			break
		}
		colonIdx := strings.Index(line, ":")
		if colonIdx == -1 {
			i++
			continue
		}
		key := strings.TrimSpace(line[:colonIdx])
		valStr := strings.TrimSpace(line[colonIdx+1:])

		if valStr == "" {
			var child interface{}
			child, i = parseYAMLLines(lines, curIndent+1, i+1)
			m[key] = child
		} else {
			if strings.HasPrefix(valStr, "\"") && strings.HasSuffix(valStr, "\"") {
				m[key] = valStr[1 : len(valStr)-1]
			} else {
				m[key] = valStr
			}
			i++
		}
	}
	return m, i
}

func parseFile(path string) (interface{}, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var v interface{}
	if err := json.Unmarshal(b, &v); err == nil {
		return v, nil
	}
	if strings.HasSuffix(path, ".yaml") || strings.HasSuffix(path, ".yml") {
		v, _ = parseYAMLLines(strings.Split(string(b), "\n"), 0, 0)
		return v, nil
	}
	return string(b), nil
}

type MathFuncs struct{}

func (MathFuncs) Add(n ...int64) int64                  { return math.AddInt(n...) }
func (MathFuncs) Mul(n ...int64) int64                  { return math.MulInt(n...) }
func (MathFuncs) Seq(start, end, step int64) []int64    { return math.Seq(start, end, step) }

type NetFuncs struct{}

func (NetFuncs) LookupIP(name string) (string, error)       { return net.LookupIP(context.Background(), name) }
func (NetFuncs) LookupIPs(name string) ([]string, error)    { return net.LookupIPs(context.Background(), name) }
func (NetFuncs) LookupCNAME(name string) (string, error)    { return net.LookupCNAME(name) }
func (NetFuncs) LookupTXT(name string) ([]string, error)    { return net.LookupTXT(name) }
func (NetFuncs) LookupSRV(name string) (*net.SRV, error)    { return net.LookupSRV(name) }
func (NetFuncs) LookupSRVs(name string) ([]*net.SRV, error) { return net.LookupSRVs(name) }

type StringsFuncs struct{}

func (StringsFuncs) ReplaceAll(old, new, s string) string { return strings.ReplaceAll(s, old, new) }
func (StringsFuncs) Split(sep, s string) []string         { return strings.Split(s, sep) }
func (StringsFuncs) TrimSpace(s string) string            { return strings.TrimSpace(s) }
func (StringsFuncs) ToUpper(s string) string              { return strings.ToUpper(s) }
func (StringsFuncs) ToLower(s string) string              { return strings.ToLower(s) }
func (StringsFuncs) HasPrefix(prefix, s string) bool      { return strings.HasPrefix(s, prefix) }
func (StringsFuncs) HasSuffix(suffix, s string) bool      { return strings.HasSuffix(s, suffix) }
func (StringsFuncs) Contains(substr, s string) bool       { return strings.Contains(s, substr) }

type EnvFuncs struct{}

func (EnvFuncs) Getenv(k string) string { return os.Getenv(k) }

var (
	datasources = make(map[string]interface{})
)

func dsFunc(name string) (interface{}, error) {
	if val, ok := datasources[name]; ok {
		return val, nil
	}
	return nil, fmt.Errorf("datasource %q not found", name)
}
