			envName := strings.TrimPrefix(url, "env:")
			datasources[alias] = os.Getenv(envName)
		} else {
			data, _ := parseFile(url)
			datasources[alias] = data
		}
	}

	var root interface{}
	defaultRoot := make(map[string]interface{})
	envMap := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			envMap[parts[0]] = parts[1]
		}
	}
	defaultRoot["Env"] = envMap
	root = defaultRoot

	for _, arg := range cFlags {
		alias, url := parseAliasURL(arg)
		var data interface{}
		if strings.HasPrefix(url, "env:") {
			envName := strings.TrimPrefix(url, "env:")
			data = os.Getenv(envName)
		} else {
			data, _ = parseFile(url)
		}

		if alias == "." {
			root = data
		} else {
			if m, ok := root.(map[string]interface{}); ok {
				m[alias] = data
			}
		}
	}

	funcMap := template.FuncMap{
		"ds":         dsFunc,
		"add":        math.AddInt,
		"mul":        math.MulInt,
		"seq":        math.Seq,
		"getenv":     os.Getenv,
		"replaceAll": func(old, new, s string) string { return strings.ReplaceAll(s, old, new) },
		"split":      func(sep, s string) []string { return strings.Split(s, sep) },
		"trimSpace":  strings.TrimSpace,
		"toUpper":    strings.ToUpper,
		"toLower":    strings.ToLower,
		"hasPrefix":  func(prefix, s string) bool { return strings.HasPrefix(s, prefix) },
		"hasSuffix":  func(suffix, s string) bool { return strings.HasSuffix(s, suffix) },
		"contains":   func(substr, s string) bool { return strings.Contains(s, substr) },
		"math":       func() MathFuncs { return MathFuncs{} },
		"net":        func() NetFuncs { return NetFuncs{} },
		"strings":    func() StringsFuncs { return StringsFuncs{} },
		"env":        func() EnvFuncs { return EnvFuncs{} },
	}

	tmpl := template.New("base").Funcs(funcMap).Delims(leftDelim, rightDelim)

	for _, tFile := range tFlags {
		b, err := os.ReadFile(tFile)
		if err == nil {
			tmpl.New(filepath.Base(tFile)).Parse(string(b))
		}
	}

	processTemplate := func(name string, tContent string, out io.Writer) error {
		t, err := tmpl.Clone()
		if err != nil {
			return err
		}
		t, err = t.New(name).Parse(tContent)
		if err != nil {
			return err
		}
		return t.Execute(out, root)
	}

	if inDir != "" {
		if outDir == "" {
			outDir = "."
		}
		filepath.WalkDir(inDir, func(path string, d fs.DirEntry, err error) error {
			if err != nil || d.IsDir() {
				return nil
			}
			rel, _ := filepath.Rel(inDir, path)
			outPath := filepath.Join(outDir, rel)
			os.MkdirAll(filepath.Dir(outPath), 0755)

			b, err := os.ReadFile(path)
			if err != nil {
				return nil
			}

			f, err := os.Create(outPath)
			if err != nil {
				return nil
			}
			defer f.Close()

			processTemplate(rel, string(b), f)
			return nil
		})
		return
	}

	var tmplContent []byte
	if inString != "" {
		tmplContent = []byte(inString)
	} else if inFile != "" && inFile != "-" {
		var err error
		tmplContent, err = os.ReadFile(inFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
			os.Exit(1)
		}
	} else {
		var err error
		tmplContent, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
			os.Exit(1)
		}
	}

	var out io.Writer = os.Stdout
	if outFile != "" && outFile != "-" {
		f, err := os.Create(outFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		out = f
	}

	err := processTemplate("main", string(tmplContent), out)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error executing template: %v\n", err)
		os.Exit(1)
	}
}
EOF
cd mygomplate && go build -o test_bin mygomplate.go
"}

